/**
 * Claims audit — every major finding, graded. Data lives in claims.json so the microsite
 * (section 09) and public/subsidy-math/claims-audit.md (generated by
 * scripts/subsidy-math/build_claims.py) never drift apart.
 * Categories: 1 proven by disclosed financial data · 2 mathematically defensible under stated
 * assumptions · 3 directionally supported, not proven · 4 unsupported or contradicted.
 */
import raw from "./claims.json";

export type Category = 1 | 2 | 3 | 4;
export type Say = "say" | "qualify" | "avoid";

export const CATEGORY_LABEL: Record<Category, string> = {
  1: "Proven by filings",
  2: "Defensible math",
  3: "Directional",
  4: "Unsupported",
};

export interface Claim {
  id: string;
  category: Category;
  say: Say;
  claim: string;
  evidence: string;
  calc?: string;
  assumptions?: string;
  confidence: "High" | "Medium" | "Low";
  counter: string;
  source: string;
}

export const CLAIMS: Claim[] = raw as Claim[];
